#include <functional>
#include <string>

struct Minimised { std::string input; int calls; };

Minimised minimise(const std::string& input, const std::function<bool(const std::string&)>& fails)
{
    std::string current{ input };
    int calls{ 0 };
    bool shrunk{ true };
    while (shrunk)
    {
        shrunk = false;
        for (std::size_t i{ 0 }; i < current.size(); ++i)
        {
            std::string candidate{ current };
            candidate.erase(i, 1);
            ++calls;
            if (fails(candidate))
            {
                current = candidate;
                shrunk = true;
                break;                         // start again from position 0
            }
        }
    }
    return { current, calls };
}

unitTests:
TEST("keeps only what matters")
{
    const auto r{ minimise("abxcdye", [](const std::string& s) { return s.find('x') != std::string::npos && s.find('y') != std::string::npos; }) };
    CHECK_EQ(r.input, std::string("xy"));
}
TEST("a substring that must stay together") { CHECK_EQ(minimise("..[[BOOM]]..", [](const std::string& s) { return s.find("BOOM") != std::string::npos; }).input, std::string("BOOM")); }
TEST("a length condition") { CHECK_EQ(minimise("abcdefghij", [](const std::string& s) { return s.size() >= 3; }).input.size(), std::size_t{ 3 }); }
TEST("already minimal") { const auto r{ minimise("z", [](const std::string& s) { return s == "z"; }) }; CHECK_EQ(r.input, std::string("z")); CHECK_EQ(r.calls, 1); }
TEST("counts the calls") { const auto r{ minimise("aab", [](const std::string& s) { return s.find('b') != std::string::npos; }) }; CHECK_EQ(r.input, std::string("b")); CHECK_EQ(r.calls, 3); }

